SELECT setting_value
FROM policy_settings
WHERE code = #{code}

SELECT FROM guestbook_notes n WHERE n.semester_label = #{semester}
AND n.state IN ('normal', 'hidden') AND n.state = 'normal'
ORDER BY n.note_id DESC

SELECT 
FROM guestbook_notes n
WHERE n.note_id = #{noteId}

mapper.update:
UPDATE guestbook_notes
SET state = 'deleted'
WHERE note_id = #{noteId}
  AND user_id = #{userId}
  AND state = 'normal'

UPDATE guestbook_drawings
SET pos_x      = #{d.posX},
    pos_y      = #{d.posY},
    width_pct  = #{d.widthPct},
    rotation   = #{d.rotation},
    opacity    = #{d.opacity},
    sort_order = #{d.sortOrder}
WHERE drawing_id = #{d.drawingId}
  AND note_id = #{noteId}
  AND state = 'normal'

UPDATE guestbook_drawings
SET state = 'deleted'
WHERE note_id = #{noteId}
  AND state = 'normal'

    AND drawing_id NOT IN
    #{id}
